    }

    h2 {
        font-size: 2rem;
    }

    section {
        padding: 60px 30px;
    }

    .container {
        padding: 0 30px;
    }

    .hero {
        padding-top: 160px;
    }

    .hero-title {
        font-size: 2.8rem;
    }

    .hero-subtitle {
        font-size: 1.2rem;
    }

