        grid-template-columns: repeat(5, 1fr);
    }

    .mission-vision {
        grid-template-columns: 1fr 1fr;
    }
}

/* Utilities */
.text-center {
    text-align: center;
}

.mt-1 { margin-top: 1rem; }
.mt-2 { margin-top: 2rem; }
.mb-1 { margin-bottom: 1rem; }
.mb-2 { margin-bottom: 2rem; }

/* Animation */
@keyframes slideIn {
    from { opacity: 0; transform: translateX(-20px); }
    to { opacity: 1; transform: translateX(0); }
}

/* Loading State */
.loading {
    opacity: 0.6;
    pointer-events: none;
}

/* About Section */
.about {
    background: #FFFFFF;
    padding-top: 80px;
}

.about-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.about-title {
    text-align: center;
    font-size: 3rem;
    color: var(--besties-pink);
    margin-bottom: 4rem;
    font-weight: 700;
    margin-top: 0;
}

/* Story Section */
.about-story {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    margin-bottom: 4rem;
    align-items: center;
}

.story-content h3 {
    color: var(--besties-pink);
    font-size: 2rem;
    margin-bottom: 1.5rem;
}

.story-content p {
    color: #555555;
    font-size: 1.1rem;
    line-height: 1.8;
    margin-bottom: 1.2rem;
}

.story-image {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    overflow: hidden;
    border-radius: 12px;
}

.story-placeholder {
    font-size: 8rem;
    opacity: 0.8;
}

.story-image-photo {
    max-width: 100%;
    height: auto;
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    transition: opacity 0.3s ease;
}

.story-image-hover {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    max-width: 100%;
    object-fit: cover;
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    opacity: 0;
    transition: opacity 0.3s ease;
}

.story-image:hover .story-image-photo {
    opacity: 0;
}

.story-image:hover .story-image-hover {
    opacity: 1;
}

.mission-info {
    margin-top: 2rem;
}

.mission-info h4 {
    color: var(--besties-pink);
    font-size: 1.5rem;
    margin-bottom: 1rem;
    font-weight: 700;
}

.mission-info p {
    color: #555555;
    font-size: 1.05rem;
    line-height: 1.7;
    margin: 0;
}

/* Mission & Vision */
.mission-vision {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
    margin-bottom: 4rem;
}

.mission-card, .vision-card {
    background: linear-gradient(135deg, var(--besties-pink) 0%, var(--besties-purple) 100%);
    color: white;
    padding: 2.5rem;
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(255, 107, 157, 0.15);
}

.mission-card h3, .vision-card h3 {
    color: white;
    font-size: 1.8rem;
    margin-bottom: 1rem;
}

.mission-card p, .vision-card p {
    color: rgba(255, 255, 255, 0.95);
    font-size: 1.05rem;
    line-height: 1.7;
    margin: 0;
}

/* Values Section */
.values-section {
    margin-bottom: 4rem;
}

.values-section h3 {
    text-align: center;
    color: var(--besties-pink);
    font-size: 2rem;
    margin-bottom: 2.5rem;
}

.values-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
}

.value-item {
    background: #FAFAFA;
    padding: 1.8rem;
    border-radius: 12px;
    text-align: center;
    border: 1px solid #EEEEEE;
    transition: all 0.3s ease;
}

.value-item:hover {
    transform: translateY(-8px);
    border-color: var(--besties-pink);
    box-shadow: 0 15px 40px rgba(255, 107, 157, 0.1);
}

.value-icon {
    font-size: 2.5rem;
    display: block;
    margin-bottom: 1rem;
}

.value-item h4 {
    color: var(--besties-pink);
    font-size: 1.3rem;
    margin-bottom: 0.8rem;
}

.value-item p {
    color: #666666;
    font-size: 0.95rem;
    line-height: 1.6;
    margin: 0;
}

/* Brand Promise Section */
.brand-promise-section {
    background: linear-gradient(135deg, var(--besties-lavender) 0%, #E8F0FF 100%);
    padding: 3rem;
    border-radius: 15px;
    text-align: center;
}

.brand-promise-section h3 {
    color: var(--besties-pink);
    font-size: 2rem;
    margin-bottom: 2rem;
}

.promise-items {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 2rem;
}

.promise-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
}

.promise-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 60px;
    height: 60px;
    background: linear-gradient(135deg, var(--besties-pink) 0%, var(--besties-purple) 100%);
    color: white;
    border-radius: 50%;
    font-weight: 700;
    font-size: 1.5rem;
}

.promise-item p {
    color: #333333;
    font-size: 1.1rem;
    font-weight: 500;
    margin: 0;
}

/* Responsive */
@media (min-width: 768px) {
    .about-story {
        grid-template-columns: 1fr 1fr;
    }

    .mission-vision {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 767px) {
    .about-title {
        font-size: 2rem;
    }

    .mission-vision {
        grid-template-columns: 1fr;
    }

    .story-placeholder {
        font-size: 5rem;
    }
}

/* Podcast Section */
.podcast {
    padding: 80px 0;
    background: linear-gradient(135deg, #FFF5F7 0%, #F5F0FF 100%);
}

.podcast-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

.podcast-title {
    text-align: center;
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
}

.podcast-subtitle {
    text-align: center;
    font-size: 1.1rem;
    color: var(--besties-purple);
    margin-bottom: 4rem;
}

/* YouTube Thumbnail in Card */
.youtube-thumbnail {
    position: relative;
    padding: 0 !important;
}

.youtube-thumbnail img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.youtube-link {
    display: flex;
    width: 100%;
    height: 100%;
    text-decoration: none;
}

/* Podcast Carousel */
.podcast-carousel {
    display: flex;
    align-items: center;
    gap: 2rem;
    margin-bottom: 6rem;
}

.carousel-btn {
    background: linear-gradient(135deg, var(--besties-pink) 0%, var(--besties-purple) 100%);
    border: none;
    width: 50px;
    height: 50px;
    border-radius: 50%;
    color: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(255, 107, 157, 0.3);
    flex-shrink: 0;
}

.carousel-btn:hover:not(:disabled) {
    transform: scale(1.1);
    box-shadow: 0 8px 25px rgba(255, 107, 157, 0.5);
}

.carousel-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.carousel-btn svg {
    width: 24px;
    height: 24px;
}

.carousel-container {
    flex: 1;
    overflow: hidden;
    border-radius: 15px;
}

.carousel-track {
    display: flex;
    gap: 2rem;
    transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.podcast-cover {
    flex: 0 0 280px;
    height: 360px;
    border-radius: 12px;
    overflow: hidden;
    cursor: pointer;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
    transition: all 0.3s ease;
    display: flex;
    flex-direction: column;
}

.podcast-cover:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 50px rgba(255, 107, 157, 0.3);
}

.cover-image {
    width: 100%;
    flex: 0 0 85%;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.podcast-cover h4 {
    width: 100%;
    flex: 0 0 auto;
    padding: 0.6rem;
    background: rgba(0, 0, 0, 0.85);
    color: white;
    font-size: 0.8rem;
    margin: 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-align: center;
    line-height: 1.2;
    word-break: break-word;
}

/* Podcast CTA */
.podcast-cta {
    text-align: center;
    padding: 4rem 2rem;
    background: linear-gradient(135deg, rgba(255, 107, 157, 0.1) 0%, rgba(213, 166, 224, 0.1) 100%);
    border-radius: 15px;
    margin-top: 4rem;
}

.podcast-cta h3 {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.podcast-cta p {
    font-size: 1.1rem;
    color: var(--besties-purple);
    margin-bottom: 2rem;
}

.subscribe-buttons {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
}


