        font-size: 1rem;
        margin-bottom: 2rem;
    }

    .shop-carousel {
        gap: 1rem;
    }

    .shop-carousel .carousel-btn {
        width: 40px;
        height: 40px;
    }

    .shop-carousel .carousel-btn svg {
        width: 20px;
        height: 20px;
    }

    .shop-carousel-container {
        height: 350px;
    }

    .product-card-carousel {
        flex: 0 0 200px;
        padding: 1.5rem 1rem;
        height: 300px;
    }

    .product-bg {
        height: 150px;
    }

    .product-circle {
        width: 100px;
        height: 100px;
        font-size: 2.5rem;
    }

    .product-card-carousel h4 {
        font-size: 1rem;
    }

    .product-card-carousel:nth-child(1),
    .product-card-carousel:nth-child(2) {
        transform: rotateY(25deg) rotateZ(-10deg) translateZ(-50px) scale(0.6) !important;
        opacity: 0.5;
    }

    .product-card-carousel:nth-child(3) {
        transform: rotateY(0deg) rotateZ(0deg) translateZ(0px) scale(1) !important;
    }

    .product-card-carousel:nth-child(4),
    .product-card-carousel:nth-child(5) {
        transform: rotateY(-25deg) rotateZ(10deg) translateZ(-50px) scale(0.6) !important;
        opacity: 0.5;
    }
}

@media (max-width: 480px) {
    /* Extra small screens */
    .nav-pill {
        padding: 8px 10px;
    }

    .nav-item {
        padding: 8px 12px;
    }

    .nav-icon {
        width: 16px;
        height: 16px;
    }

    .hero-title {
        font-size: 1.5rem !important;
    }

    .hero-subtitle {
        font-size: 0.95rem;
    }

    .about-title {
        font-size: 1.5rem;
    }

    .podcast-title {
        font-size: 1.5rem;
    }

    .podcast-subtitle {
        font-size: 0.9rem;
    }

    .gallery-container {
        height: 250px;
    }

    .podcast-cover {
        width: 130px;
        height: 180px;
    }

    .podcast-cover:nth-child(1) {
        transform: translateX(-140px) rotateY(-35deg) rotateZ(-15deg) scale(0.65);
    }

    .podcast-cover:nth-child(2) {
        transform: translateX(-70px) rotateY(-15deg) rotateZ(-5deg) scale(0.75);
    }

    .podcast-cover:nth-child(3) {
        transform: translateX(0) rotateY(0) rotateZ(0) scale(0.95);
    }

    .podcast-cover:nth-child(4) {
        transform: translateX(70px) rotateY(15deg) rotateZ(5deg) scale(0.75);
    }

    .podcast-cover:nth-child(5) {
        transform: translateX(140px) rotateY(35deg) rotateZ(15deg) scale(0.65);
    }

    .gallery-info h3 {
        font-size: 1.2rem;
    }

    .gallery-info p {
        font-size: 0.9rem;
    }
}

/* Mobile Optimization - Extra Small Devices (< 480px) */
@media (max-width: 479px) {
    .hero {
        padding-top: 100px;
        padding-left: 15px;
        padding-right: 15px;
    }

    .hero-title {
        font-size: 2rem;
        -webkit-text-stroke: 3px white;
        text-stroke: 3px white;
    }

    .hero-subtitle {
        font-size: 0.4rem;
    }

    .hero-ctas {
        flex-direction: column;
    }

    .btn {
        padding: 10px 20px;
        font-size: 0.9rem;
    }

    .besties-characters {
        height: 50vh;
    }

    h1 { font-size: 1.8rem; }
    h2 { font-size: 1.5rem; }
    h3 { font-size: 1.2rem; }
    h4 { font-size: 1rem; }

    .navbar {
        top: 15px;
    }

    .nav-pill {
        padding: 8px 12px;
        gap: 0;
    }

    .nav-item {
        padding: 8px 12px;
    }

    .nav-icon {
        width: 18px;
        height: 18px;
    }

    .experience-card, .shop-product-card {
        padding: 12px;
    }

    .experience-image {
        height: 200px;
    }

    .shop-product-image {
        height: 150px;
    }

    .podcast-cover {
        min-width: 150px;
    }

    .about-story {
        flex-direction: column;
    }

    .story-image {
        margin-top: 2rem;
    }

    .bestie-strip {
        margin-bottom: 2rem;
    }

    .cart-drawer {
        width: 90%;
    }

    .checkout-modal {
        width: 95%;
        padding: 15px;
    }

    .shop-modal-content {
        padding: 15px;
    }

    .shop-products-grid {
        grid-template-columns: 1fr;
    }
}

/* Mobile Optimization - Small Devices (480px - 767px) */
@media (max-width: 767px) {
    .hero {
        padding-top: 120px;
    }

    .hero-title {
        font-size: 2.5rem;
        -webkit-text-stroke: 4px white;
        text-stroke: 4px white;
    }

    .hero-subtitle {
        font-size: 0.5rem;
    }

    .hero-ctas {
        flex-direction: column;
        gap: 10px;
    }

    .btn {
        width: 90%;
        max-width: 300px;
        padding: 12px 24px;
        font-size: 0.95rem;
    }

    .besties-characters {
        height: 60vh;
    }

    h1 { font-size: 2rem; }
    h2 { font-size: 1.6rem; }
    h3 { font-size: 1.3rem; }

    .section-subtitle {
        font-size: 1rem;
    }

    .navbar {
        top: 20px;
    }

    .nav-pill {
        padding: 10px 15px;
    }

    .nav-label {
        display: none !important;
    }

    .experience-carousel,
    .podcast-carousel {
        overflow-x: auto;
    }

    .carousel-btn {
        display: none;
    }

    .experience-card {
        min-width: 85%;
        padding: 15px;
    }

    .shop-product-card {
        padding: 15px;
    }

    .shop-products-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 15px;
    }

    .about-container {
        padding: 20px;
    }

    .about-story {
        flex-direction: column;
        gap: 2rem;
    }

    .story-image {
        margin-top: 1rem;
    }

    .cart-drawer {
        width: 85%;
        right: 0;
    }

    .checkout-modal {
        width: 90%;
        max-height: 95vh;
        overflow-y: auto;
    }

    .checkout-content {
        flex-direction: column;
    }

    .checkout-form,
    .checkout-summary {
        width: 100%;
    }

    .shop-modal-content {
        padding: 20px;
        max-height: 90vh;
        overflow-y: auto;
    }

    .contact-form {
        padding: 0;
    }

    .form-group {
        margin-bottom: 15px;
    }

    .contact-form input,
    .contact-form textarea {
        padding: 12px;
        font-size: 16px;
    }
}

/* Tablet Optimization (768px - 1024px) */
@media (min-width: 768px) and (max-width: 1024px) {
    .hero {
        padding-top: 150px;
    }

    .hero-title {
        font-size: 3.5rem;
        -webkit-text-stroke: 4px white;
        text-stroke: 4px white;
    }

    .hero-subtitle {
        font-size: 0.5rem;
    }

    .besties-characters {
        height: 70vh;
    }

    .experience-card,
    .shop-product-card {
        padding: 18px;
    }

    .shop-products-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .podcast-carousel {
        overflow-x: auto;
    }

    .carousel-btn {
        display: none;
    }

    .experience-card {
        min-width: 70%;
    }

    .about-story {
        gap: 2rem;
    }

    .cart-drawer {
        width: 70%;
    }

    .checkout-modal {
        width: 85%;
    }

    .shop-modal-content {
        padding: 30px;
    }

    .shop-products-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 20px;
    }

    h1 { font-size: 2.2rem; }
    h2 { font-size: 1.8rem; }
    h3 { font-size: 1.4rem; }
}

/* Large Devices (1025px+) */
@media (min-width: 1025px) {
    .hero-title {
        font-size: 5rem;
    }

    .hero-subtitle {
        font-size: 0.5rem;
    }

    .shop-products-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

/* Print Styles */
@media print {
    nav, footer {
        display: none;
    }
}